/* Le CSS placé ici sera appliqué à tous les habillages. */

/* Targeted Translations */
.translations-columm {
   background-color: #FFFFE0;
   width:48%;
   text-align: left;
   vertical-align: top;
}

/* Fanitrihana ny teny "Fandraisana" eo amin'ny pejy fandraisana */
.page-Wiktionary_Fandraisana .firstHeading,
.page-Fandraisana #firstHeading  {
	display: none; 
}

div.mw-content-ltr {
	text-align: justify;
}

.mw-line-even {
	background-color: #F0F0F0;
}

#catlinks {
	text-align: left;
}

.rcoptions {
	border-radius: 20px;
}

.mw-body h3 {
	font-size: 132%;
	color: rgb(138, 13, 2);
}

.mw-body h2 {
font-size: 150%;
background-color: rgb(229, 239, 255);
border-bottom: 1px solid #00C8DA;
padding-left: 10px;
padding-right: 10px;
padding-top: 15px;
padding-bottom: 15px;
border-radius: 0px 20px 0px 0px;
}

h2 .editsection {
	font-size: 50%;
}

